		tokens[i].Text = expanded
	}
	return tokens, nil
}

// expandTokenText expands the {$NAME} and {$NAME:default} notations in
// s. token supplies the source location used in error messages.
func expandTokenText(s string, env envSnapshot, token *Token) (string, error) {
	var out strings.Builder
	out.Grow(len(s))

	for i := 0; i < len(s); {
		switch {
		// Escaped notation: \{$ ... \}. Only a pair that encloses an
		// environment-variable notation (content beginning with '$')
		// is treated as an escape; other escaped braces stay literal.
		// The enclosed text is emitted verbatim, with the escaping
		// backslashes removed, and the environment is never consulted.
		case isEscapedEnvOpen(s, i):
			closeRel := strings.Index(s[i+len(escapedEnvOpen):], escapedEnvClose)
			if closeRel < 0 {
				// No matching "\}"; this is not a complete escaped
				// notation, so treat the backslash as an ordinary byte.
				out.WriteByte(s[i])
				i++
				continue
			}
			closeStart := i + len(escapedEnvOpen) + closeRel
			out.WriteString(envOpen)
			out.WriteString(s[i+len(escapedEnvOpen) : closeStart])
			out.WriteString(envClose)
			i = closeStart + len(escapedEnvClose)

		// Environment variable notation: {$NAME} or {$NAME:default}.
		case isEnvOpen(s, i):
			closeRel := strings.IndexByte(s[i+len(envOpen):], envCloseByte)
			if closeRel < 0 {
				return "", envExpandErr(token,
					"environment variable notation is not closed: %q",
					s[i:])
			}
			closeStart := i + len(envOpen) + closeRel
			name, hasDefault, defaultVal := parseEnvNotation(s[i+len(envOpen) : closeStart])
			if name == "" {
				return "", envExpandErr(token,
					"environment variable name must not be empty: {%s}",
					s[i+len(envOpen):closeStart])
			}
			if hasDefault && defaultVal == "" {
				return "", envExpandErr(token,
					"environment variable %q has a default separator but no default value",
					name)
			}

			val, found := env[name]
			if !found {
				if !hasDefault {
					return "", envExpandErr(token,
						"environment variable %q is not set; use {%s:default} to provide a default",
						name, name)
				}
				val = defaultVal
			}
			// The value is spliced into the current token as raw bytes;
			// it is never scanned for further notations.
			out.WriteString(val)
			i = closeStart + 1

		default:
			out.WriteByte(s[i])
			i++
		}
	}

	return out.String(), nil
}

// parseEnvNotation splits the body of a {$...} notation into the
// variable name and an optional default value separated by the first
// default delimiter.
func parseEnvNotation(body string) (name string, hasDefault bool, defaultVal string) {
	name, defaultVal, hasDefault = strings.Cut(body, envVarDefaultDelimiter)
	return
}

// envExpandErr formats an expansion error with the token's source
// location, mirroring the file:line style of Dispenser.WrapErr.
func envExpandErr(token *Token, format string, args ...any) error {
	msg := fmt.Sprintf(format, args...)
	if len(token.imports) > 0 {
		return fmt.Errorf("%s, at %s:%d import chain ['%s']",
			msg, token.File, token.Line, strings.Join(token.imports, "','"))
	}
	return fmt.Errorf("%s, at %s:%d", msg, token.File, token.Line)
}

func isEnvOpen(s string, i int) bool {
	return i+len(envOpen) <= len(s) && s[i:i+len(envOpen)] == envOpen
}

func isEscapedEnvOpen(s string, i int) bool {
	return i+len(escapedEnvOpen) < len(s) &&
		s[i:i+len(escapedEnvOpen)] == escapedEnvOpen
}

var (
	// envOpen and envClose bound an environment variable notation.
	envOpen  = "{$"
	envClose = "}"

	envCloseByte = byte('}')

	// escapedEnvOpen and escapedEnvClose delimit an escaped notation
	// that must be preserved literally: \{$NAME\} becomes {$NAME}.
	escapedEnvOpen  = `\{$`
	escapedEnvClose = `\}`

	// envVarDefaultDelimiter separates a variable name from its default.
	envVarDefaultDelimiter = ":"
)

