// staticBody extracts the first static_response body from adapted JSON.
func staticBodies(t *testing.T, out []byte) []string {
	t.Helper()
	var doc struct {
		Apps struct {
			HTTP struct {
				Servers map[string]struct {
					Routes []struct {
						Handle []struct {
							Handler string `json:"handler"`
							Body    string `json:"body"`
						} `json:"handle"`
					} `json:"routes"`
				} `json:"servers"`
			} `json:"http"`
		} `json:"apps"`
	}
	if err := json.Unmarshal(out, &doc); err != nil {
		t.Fatalf("unmarshaling adapted config: %v\n%s", err, out)
	}
	var bodies []string
	for _, srv := range doc.Apps.HTTP.Servers {
		for _, route := range srv.Routes {
			for _, h := range route.Handle {
				var sub struct {
					Routes []struct {
						Handle []struct {
							Handler string `json:"handler"`
							Body    string `json:"body"`
						} `json:"handle"`
					} `json:"routes"`
				}
				if err := json.Unmarshal(h.Body, nil); err == nil && strings.Contains(h.Handler, "subroute") {
					// handled below by re-decoding the raw handler
				}
			}
		}
	}
	// simpler: decode the whole tree generically and collect static_response bodies
	var generic any
	if err := json.Unmarshal(out, &generic); err != nil {
		t.Fatalf("unmarshaling adapted config generically: %v", err)
	}
	var walk func(any)
	walk = func(v any) {
		switch val := v.(type) {
		case map[string]any:
			if val["handler"] == "static_response" {
				if body, ok := val["body"].(string); ok {
					bodies = append(bodies, body)
				}
			}
			for _, vv := range val {
				walk(vv)
			}
		case []any:
			for _, vv := range val {
				walk(vv)
			}
		}
	}
	walk(generic)
	return bodies
}

