func TestEdges(t *testing.T) {
	os.Setenv("X", "xval")
	os.Setenv("Q", `he"llo`)
	cases := []string{
		// escaped notation with spaces in default
		"ex.test {\n\trespond \\{$NOPE:my default\\}\n}\n",
		// adjacent notations in one token
		"ex.test {\n\trespond {$X}-{$X}\n}\n",
		// notation inside double quotes, value containing a quote
		"ex.test {\n\trespond \"v={$Q}\"\n}\n",
		// comment with notation must not be expanded
		"ex.test {\n\t# {$NOPE}\n\trespond ok\n}\n",
		// unclosed inside quotes stays in token until quote
		"ex.test {\n\trespond \"{$UNCLOSED\"\n}\n",
		// ordinary braces still structural
		"ex.test {\n\trespond a\n}\n",
		// value with tabs
		"ex.test {\n\trespond [{$X}]\n}\n",
	}
	for _, c := range cases {
		fmt.Printf("CASE %q\n", c)
		adapt(c)
	}
}
